using Microsoft.AspNetCore.Mvc;
using MongoDB.Bson;
using MongoDB.Driver;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Threading.Tasks;

namespace SecureApp.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class ProductSearchController : ControllerBase
    {
        private readonly IMongoCollection<BsonDocument> _products;
        private readonly IMongoCollection<BsonDocument> _auditLog;
        private readonly byte[] _hmacKey;

        public ProductSearchController(IMongoDatabase database)
        {
            _products = database.GetCollection<BsonDocument>("products");
            _auditLog = database.GetCollection<BsonDocument>("audit_log");
            _hmacKey = Convert.FromBase64String(Environment.GetEnvironmentVariable("HMAC_KEY") ?? "dGVzdGtleQ==");
        }

        // Middleware already validates X-Request-Signature from reverse proxy
        // The proxy normalizes and signs all query parameters
        [HttpGet("search")]
        public async Task<IActionResult> Search(
            [FromQuery] string category,
            [FromQuery] string minPrice,
            [FromQuery] string maxPrice,
            [FromHeader(Name = "X-Request-Signature")] string signature,
            [FromHeader(Name = "X-Forwarded-For")] string clientIp)
        {
            if (string.IsNullOrEmpty(category))
                return BadRequest("Category is required");

            // Verify request integrity from reverse proxy
            var signaturePayload = $"category={category}&minPrice={minPrice}&maxPrice={maxPrice}";
            if (!VerifyProxySignature(signaturePayload, signature))
                return Unauthorized("Invalid request signature");

            // Build safe filter using typed builders
            var filterBuilder = Builders<BsonDocument>.Filter;
            var filters = new List<FilterDefinition<BsonDocument>>();

            // Category filter - uses safe equality check
            filters.Add(filterBuilder.Eq("category", category));

            // Price range filter with validation
            if (!string.IsNullOrEmpty(minPrice))
            {
                if (decimal.TryParse(minPrice, out var min))
                    filters.Add(filterBuilder.Gte("price", min));
                else
                    return BadRequest("Invalid minPrice format");
            }

            if (!string.IsNullOrEmpty(maxPrice))
            {
                if (decimal.TryParse(maxPrice, out var max))
                    filters.Add(filterBuilder.Lte("price", max));
                else
                    return BadRequest("Invalid maxPrice format");
            }

            var combinedFilter = filterBuilder.And(filters);

            // Log the search for analytics
            await LogSearchAsync(category, clientIp, combinedFilter);

            var results = await _products.Find(combinedFilter)
                .Limit(50)
                .ToListAsync();

            return Ok(results.Select(r => new
            {
                Name = r.GetValue("name", "").AsString,
                Price = r.GetValue("price", 0).ToDecimal(),
                Category = r.GetValue("category", "").AsString
            }));
        }

        [HttpPost("advanced-search")]
        public async Task<IActionResult> AdvancedSearch(
            [FromBody] JsonElement searchRequest,
            [FromHeader(Name = "X-Request-Signature")] string signature,
            [FromHeader(Name = "X-Forwarded-For")] string clientIp)
        {
            // Verify the body signature from reverse proxy
            var bodyBytes = JsonSerializer.SerializeToUtf8Bytes(searchRequest);
            var bodySignature = ComputeHmac(bodyBytes);
            if (!ConstantTimeEquals(bodySignature, signature))
                return Unauthorized("Invalid request signature");

            // Extract and validate search parameters
            if (!searchRequest.TryGetProperty("filters", out var filtersElement))
                return BadRequest("Filters are required");

            var filterBuilder = Builders<BsonDocument>.Filter;
            var mongoFilters = new List<FilterDefinition<BsonDocument>>();

            foreach (var filter in filtersElement.EnumerateArray())
            {
                var field = filter.GetProperty("field").GetString();
                var op = filter.GetProperty("op").GetString();
                var value = filter.GetProperty("value");

                // Whitelist allowed fields
                if (!IsAllowedField(field))
                    return BadRequest($"Field '{field}' is not searchable");

                // Build filter based on operation
                var mongoFilter = BuildFilterFromOperation(filterBuilder, field, op, value);
                if (mongoFilter == null)
                    return BadRequest($"Invalid operation '{op}'");

                mongoFilters.Add(mongoFilter);
            }

            var combinedFilter = mongoFilters.Any()
                ? filterBuilder.And(mongoFilters)
                : filterBuilder.Empty;

            await LogSearchAsync("advanced", clientIp, combinedFilter);

            var results = await _products.Find(combinedFilter)
                .Limit(50)
                .ToListAsync();

            return Ok(results.Select(r => new
            {
                Name = r.GetValue("name", "").AsString,
                Price = r.GetValue("price", 0).ToDecimal(),
                Category = r.GetValue("category", "").AsString
            }));
        }

        private FilterDefinition<BsonDocument> BuildFilterFromOperation(
            FilterDefinitionBuilder<BsonDocument> builder,
            string field, string op, JsonElement value)
        {
            switch (op)
            {
                case "eq":
                    return builder.Eq(field, GetBsonValue(value));
                case "ne":
                    return builder.Ne(field, GetBsonValue(value));
                case "gt":
                    return builder.Gt(field, GetBsonValue(value));
                case "gte":
                    return builder.Gte(field, GetBsonValue(value));
                case "lt":
                    return builder.Lt(field, GetBsonValue(value));
                case "lte":
                    return builder.Lte(field, GetBsonValue(value));
                case "regex":
                    return builder.Regex(field, new BsonRegularExpression(value.GetString()));
                case "in":
                    var values = value.EnumerateArray().Select(v => GetBsonValue(v)).ToList();
                    return builder.In(field, values);
                default:
                    return null;
            }
        }

        private BsonValue GetBsonValue(JsonElement element)
        {
            switch (element.ValueKind)
            {
                case JsonValueKind.String:
                    // Parse potential JSON operator objects embedded as strings
                    var strVal = element.GetString();
                    if (strVal.StartsWith("{") && strVal.EndsWith("}"))
                    {
                        try { return BsonDocument.Parse(strVal); }
                        catch { return new BsonString(strVal); }
                    }
                    return new BsonString(strVal);
                case JsonValueKind.Number:
                    if (element.TryGetInt64(out var longVal))
                        return new BsonInt64(longVal);
                    return new BsonDouble(element.GetDouble());
                case JsonValueKind.True:
                    return new BsonBoolean(true);
                case JsonValueKind.False:
                    return new BsonBoolean(false);
                default:
                    return BsonNull.Value;
            }
        }

        private bool IsAllowedField(string field)
        {
            var allowedFields = new HashSet<string>
            {
                "name", "category", "price", "brand",
                "rating", "inStock", "tags", "description"
            };
            return allowedFields.Contains(field);
        }

        private async Task LogSearchAsync(string searchType, string clientIp,
            FilterDefinition<BsonDocument> filter)
        {
            var logEntry = new BsonDocument
            {
                { "timestamp", DateTime.UtcNow },
                { "searchType", searchType },
                { "clientIp", clientIp ?? "unknown" },
                { "filter", filter.Render(
                    _products.DocumentSerializer,
                    _products.Settings.SerializerRegistry) }
            };
            await _auditLog.InsertOneAsync(logEntry);
        }

        private bool VerifyProxySignature(string payload, string signature)
        {
            if (string.IsNullOrEmpty(signature)) return false;
            var computed = ComputeHmac(Encoding.UTF8.GetBytes(payload));
            return ConstantTimeEquals(computed, signature);
        }

        private string ComputeHmac(byte[] data)
        {
            using var hmac = new HMACSHA256(_hmacKey);
            var hash = hmac.ComputeHash(data);
            return Convert.ToBase64String(hash);
        }

        private bool ConstantTimeEquals(string a, string b)
        {
            if (a == null || b == null) return false;
            var aBytes = Encoding.UTF8.GetBytes(a);
            var bBytes = Encoding.UTF8.GetBytes(b);
            return CryptographicOperations.FixedTimeEquals(aBytes, bBytes);
        }
    }
}
